children.onClick:
{{
(() => {
  const evaluateAndRefresh = () => {
    EvaluateGovernance.run().then(() => {
      GetApplicationHistory.run();
      GetTrainingStatus.run();
    });
  };

  if (appsmith.store.currentApplicationId) {
    UpdateApplication.run(
      () => {
        showAlert("Application updated successfully", "success");
        evaluateAndRefresh();
      },
      () => {
        showAlert("Application update failed", "error");
      }
    );
  } else {
    CreateApplication.run(
      () => {
        storeValue("currentApplicationId", CreateApplication.data.id);
        showAlert("Application submitted successfully", "success");
        evaluateAndRefresh();
      },
      () => {
        showAlert("Application submission failed", "error");
      }
    );
  }
})();
}}

